import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));
        StringTokenizer st;

        int N = Integer.parseInt(br.readLine());
        List<List<Mint>> p = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            List<Mint> row = new ArrayList<>();
            for (int j = 0; j < N; j++) {
                double val = Double.parseDouble(st.nextToken());
                row.add(new Mint((long)(val * 100)));
            }
            p.add(row);
        }

        Map<BitSet, Mint> currentState = new HashMap<>();
        Map<BitSet, Mint> nextState = new HashMap<>();
        {
            BitSet b = new BitSet(N);
            b.set(0);
            currentState.put(b, new Mint(1));
        }

        for (int i = 0; i < N; i++) {
            for (Map.Entry<BitSet, Mint> entry : currentState.entrySet()) {
                BitSet b = (BitSet) entry.getKey().clone();
                List<Integer> ones = new ArrayList<>();
                for (int idx = 0; idx < (1 << N); idx++) {
                    if (b.get(idx)) {
                        ones.add(idx);
                    }
                }
                for (int e = 0; e < (1 << N); e++) {
                    Mint pr = new Mint(1);
                    for (int j = 0; j < N; j++) {
                        if (((e >> j) & 1) == 1) {
                            pr = pr.multiply(p.get(i).get(j));
                        } else {
                            pr = pr.multiply(Mint.one().subtract(p.get(i).get(j)));
                        }
                    }
                    BitSet nb = new BitSet(N);
                    for (int x : ones) {
                        for (int r = 0; r < N; r++) {
                            if (((e >> r) & 1) == 1 && !b.get(r)) {
                                BitSet temp = (BitSet) b.clone();
                                temp.set(r);
                                nb.or(temp);
                            }
                        }
                    }
                    nextState.put(nb, nextState.getOrDefault(nb, new Mint(0)).add(entry.getValue().multiply(pr)));
                }
            }
            currentState = new HashMap<>(nextState);
            nextState.clear();
        }

        Mint answer = new Mint(0);
        for (Map.Entry<BitSet, Mint> entry : currentState.entrySet()) {
            BitSet b = entry.getKey();
            if (b.get((1 << N) - 1)) {
                answer = answer.add(entry.getValue());
            }
        }
        pw.println(answer);
        pw.flush();
    }

    static class Mint {
        private long v;
        private static final long MOD = 1000000007;

        public Mint(long v) {
            this.v = normS(v % MOD);
        }

        public static Mint one() {
            return new Mint(1);
        }

        private static long normS(long x) {
            return x >= 0 ? x : x + MOD;
        }

        public Mint add(Mint b) {
            return new Mint(normS(this.v + b.v));
        }

        public Mint subtract(Mint b) {
            return new Mint(normS(this.v - b.v + MOD));
        }

        public Mint multiply(Mint b) {
            return new Mint((this.v * b.v) % MOD);
        }

        public Mint inverse() {
            long x, y;
            extgcd(this.v, MOD, new long[1], new long[1]);
            return new Mint(normS(x));
        }

        public Mint divide(Mint b) {
            return this.multiply(b.inverse());
        }

        private static long extgcd(long a, long b, long[] x, long[] y) {
            if (b == 0) {
                x[0] = 1;
                y[0] = 0;
                return a;
            }
            long d = extgcd(b, a % b, x, y);
            long temp = x[0];
            x[0] = y[0];
            y[0] = temp - (a / b) * y[0];
            return d;
        }

        @Override
        public String toString() {
            return String.valueOf(v);
        }
    }
